'use client'

import { useState, useEffect } from 'react'
import { supabase } from '@/lib/supabase'
import { useLang } from '@/lib/LanguageContext'

export type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

// Shared farmer-side order shape. Superset of the columns the dashboard and the
// Orders page each fetch, so the same card renders on both.
export type FarmerOrder = {
  id: string
  farmer_id: string
  order_code?: string | null
  produce_listing_id: string | null
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  buyer_name: string | null
  buyer_phone: string | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined' | 'cancelled'
  payment_method?: string | null
  payment_status: string | null
  utr_number?: string | null
  decline_reason: string | null
  refund_status?: string | null
  refund_amount?: number | null
  refunded_at?: string | null
  created_at: string
  delivery_type?: 'self_pickup' | 'home_delivery' | 'courier' | null
  delivery_status?: DeliveryStatus | null
  delivery_boy_id?: string | null
  fulfillment_date?: string | null
  collected_at?: string | null
  shipped_at?: string | null
  received_at?: string | null
  // When the farmer acknowledged a buyer-cancelled order (moves it to history).
  acknowledged_at?: string | null
}

// An approved order is "resolved" (and so leaves the farmer's active list) once:
//   self_pickup   → the buyer collected it (collected_at set)
//   courier       → the buyer confirmed receipt (received_at set); note a
//                   shipped-but-unreceived courier order stays active
//   home_delivery → rider flow: the rider delivered it (delivery_status
//                   'delivered'); farmer-ships flow: the buyer confirmed
//                   receipt (received_at set)
export function isResolved(o: FarmerOrder): boolean {
  // A buyer-cancelled order is NOT resolved until the farmer acknowledges it.
  // Until then it stays in the active list so the farmer sees the cancellation
  // instead of it silently dropping into history. Once acknowledged, it's done.
  if (o.status === 'cancelled') return !!o.acknowledged_at
  if (o.status !== 'approved') return false
  if (o.delivery_type === 'home_delivery') return o.delivery_status === 'delivered' || !!o.received_at
  if (o.delivery_type === 'courier') return !!o.received_at
  return !!o.collected_at
}

export default function OrderCard({
  order,
  processing,
  processingPaid,
  onApprove,
  onDecline,
  onAcknowledge,
  onMarkPaid,
  onUpdatePaymentStatus,
  onSetFulfillmentDate,
  onMarkPickedUp,
  onMarkShipped,
}: {
  order: FarmerOrder
  processing: boolean
  processingPaid: boolean
  onApprove: (date: string) => void
  onDecline: () => void
  onAcknowledge: () => void
  onMarkPaid: () => void
  onUpdatePaymentStatus: (status: 'completed' | 'failed' | 'pending') => void
  onSetFulfillmentDate: (date: string) => void
  onMarkPickedUp: () => void
  onMarkShipped: () => void
}) {
  const { tx, L } = useLang()
  const isDelivery = order.delivery_type === 'home_delivery'
  const isCourier = order.delivery_type === 'courier'
  const isPickup = !isDelivery && !isCourier
  const isShipped = !!order.shipped_at
  // A home delivery is in the rider flow once a rider is assigned (delivery
  // status moved past 'unassigned'). Those stay rider-closed; home deliveries
  // with no rider are farmer-shipped, so the farmer marks them Shipped.
  const riderAssigned = isDelivery
    && order.delivery_status != null
    && order.delivery_status !== 'unassigned'
  const isApproved = order.status === 'approved'
  const fulfillmentDate = order.fulfillment_date ?? ''
  // Local (not UTC) "today" so the picker still allows today's date in IST
  // evenings. Used as the minimum selectable pickup/delivery date. Computed
  // once on mount via the lazy initializer.
  const [todayStr] = useState(() => {
    const d = new Date()
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
  })

  const timeAgo = (ts: string) => {
    const diff = Date.now() - new Date(ts).getTime()
    const mins = Math.floor(diff / 60000)
    if (mins < 1) return 'just now'
    if (mins < 60) return `${mins}m ago`
    const hrs = Math.floor(mins / 60)
    if (hrs < 24) return `${hrs}h ago`
    return `${Math.floor(hrs / 24)}d ago`
  }

  const isCod = !order.payment_method || order.payment_method === 'cod'
  const isUpi = order.payment_method === 'upi'
  const isPaid = order.payment_status === 'completed'
  const isPaymentClaimed = order.payment_status === 'payment_claimed' || order.payment_status === 'pending_confirmation'

  // Buyer cancelled this order. It doesn't need the approve/decline/fulfillment
  // machinery — just a clear "cancelled by buyer" notice and an Acknowledge tap
  // that moves it out of the active list and into Order History.
  if (order.status === 'cancelled') {
    return (
      <div className="border border-red-200 bg-red-50/40 rounded-2xl overflow-hidden">
        <div className="p-3 space-y-2">
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <div className="flex items-center gap-1.5 flex-wrap">
                <p className="font-extrabold text-gray-900 text-sm leading-tight">
                  {order.buyer_name || '—'}
                </p>
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-red-100 text-red-700 whitespace-nowrap">
                  {L('Cancelled by buyer', 'కొనుగోలుదారు రద్దు చేశారు')}
                </span>
              </div>
              {order.buyer_phone && (
                <a href={`tel:+91${order.buyer_phone}`} className="text-xs font-semibold text-green-700">
                  📞 +91 {order.buyer_phone}
                </a>
              )}
            </div>
            <span className="text-[11px] text-gray-400 whitespace-nowrap mt-0.5">
              {timeAgo(order.created_at)}
            </span>
          </div>

          <div className="flex flex-wrap items-center gap-1.5 text-sm">
            <span className="font-semibold text-gray-800">{order.produce_name || '—'}</span>
            <span className="text-gray-300">·</span>
            <span className="text-gray-600">{order.quantity} {order.unit || 'kg'}</span>
            {order.total_price != null && order.total_price > 0 && (
              <>
                <span className="text-gray-300">·</span>
                <span className="font-bold text-gray-500 line-through">₹{order.total_price}</span>
              </>
            )}
          </div>

          {order.decline_reason && (
            <div className="bg-white border border-red-200 rounded-xl px-3 py-2">
              <p className="text-[10px] font-bold text-red-700 uppercase tracking-wide">
                {L('Reason', 'కారణం')}
              </p>
              <p className="text-xs text-red-800 mt-0.5 leading-snug">{order.decline_reason}</p>
            </div>
          )}

          <button
            onClick={onAcknowledge}
            disabled={processing}
            className="w-full bg-gray-700 text-white font-bold py-2.5 rounded-xl text-sm active:bg-gray-800 disabled:opacity-50"
          >
            {processing ? '…' : `✓ ${L('Acknowledge — move to history', 'గుర్తించాను — చరిత్రకు తరలించు')}`}
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className={`border rounded-2xl overflow-hidden ${isApproved ? 'border-green-200 bg-green-50/30' : 'border-gray-200'}`}>
      <div className="p-3 space-y-1.5">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <div className="flex items-center gap-1.5 flex-wrap">
              <p className="font-extrabold text-gray-900 text-sm leading-tight">
                {order.buyer_name || '—'}
              </p>
              {isApproved && (
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-green-100 text-green-800 whitespace-nowrap">
                  {tx.statusApproved}
                </span>
              )}
            </div>
            {order.buyer_phone && (
              <a href={`tel:+91${order.buyer_phone}`} className="text-xs font-semibold text-green-700">
                📞 +91 {order.buyer_phone}
              </a>
            )}
          </div>
          <div className="flex items-center gap-1.5 flex-shrink-0 mt-0.5">
            {isCod && (
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${
                isPaid ? 'bg-green-100 text-green-800' : 'bg-amber-100 text-amber-800'
              }`}>
                {isPaid ? `✓ ${tx.paymentReceived}` : tx.codBadge}
              </span>
            )}
            {isUpi && (
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${
                isPaid ? 'bg-green-100 text-green-800'
                : isPaymentClaimed ? 'bg-orange-100 text-orange-800'
                : 'bg-blue-100 text-blue-700'
              }`}>
                {isPaid ? '✓ UPI Paid' : isPaymentClaimed ? '⏳ Buyer Paid — Verify' : '📲 UPI'}
              </span>
            )}
            <span className="text-[11px] text-gray-400 whitespace-nowrap">
              {timeAgo(order.created_at)}
            </span>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-1.5 text-sm">
          <span className="font-semibold text-gray-800">{order.produce_name || '—'}</span>
          <span className="text-gray-300">·</span>
          <span className="text-gray-600">{order.quantity} {order.unit || 'kg'}</span>
          {order.total_price != null && order.total_price > 0 && (
            <>
              <span className="text-gray-300">·</span>
              <span className="font-bold text-green-700">₹{order.total_price}</span>
            </>
          )}
        </div>

        {order.pickup_location && (
          <p className="text-xs text-gray-500">📍 {order.pickup_location}</p>
        )}

        {order.delivery_type === 'home_delivery' && (
          <DeliveryTagForFarmer order={order} />
        )}

        {/* Pickup / delivery date. For a pending order this is the gate to
            approval — the farmer chooses a date, then confirms below. For an
            approved order it shows the scheduled date and can still be changed.
            Either way the buyer sees it on their order page. */}
        <div className="pt-1">
          <label className="text-[11px] font-bold text-gray-600 block mb-1">
            📅 {isPickup ? tx.pickupDateLabel : tx.deliveryDateLabel}
          </label>
          <input
            type="date"
            value={fulfillmentDate}
            min={todayStr}
            onChange={(e) => onSetFulfillmentDate(e.target.value)}
            className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm bg-white focus:border-green-500 focus:outline-none"
          />
          {isApproved && fulfillmentDate && !(isCourier && isShipped) && (
            <p className="text-[11px] font-semibold text-green-700 mt-1">
              ⏳ {isPickup ? tx.awaitingPickup : tx.awaitingDelivery}
            </p>
          )}
        </div>
      </div>

      {isUpi && isPaymentClaimed && (
        <div className="mx-3 mb-2 bg-orange-50 border border-orange-200 rounded-xl px-3 py-3 space-y-2.5">
          <div>
            <p className="text-xs font-bold text-orange-800">
              📲 Buyer says they paid via UPI
            </p>
            <p className="text-[11px] text-orange-700 mt-0.5">
              Open your UPI app and confirm you received ₹{order.total_price ?? '?'} from {order.buyer_name || 'buyer'}.
            </p>
            {order.utr_number && (
              <p className="text-[11px] text-orange-700 mt-0.5">
                UTR: <span className="font-mono font-semibold">{order.utr_number}</span>
              </p>
            )}
          </div>
          <p className="text-xs font-bold text-gray-700">
            {L('Update Payment Status', 'చెల్లింపు స్థితి నవీకరించండి')}
          </p>
          <p className="text-[11px] text-gray-500 -mt-1">{tx.receivedApprovesOrderHint}</p>
          <div className="grid grid-cols-3 gap-2">
            <button
              onClick={() => onUpdatePaymentStatus('completed')}
              disabled={processingPaid}
              className="bg-green-700 text-white font-bold py-2.5 rounded-xl text-[11px] leading-tight disabled:opacity-50 active:bg-green-800 px-1"
            >
              {L('✓ Received & Approve', 'అందింది & ఆమోదం')}
            </button>
            <button
              onClick={() => onUpdatePaymentStatus('failed')}
              disabled={processingPaid}
              className="border-2 border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-xs disabled:opacity-50 active:bg-red-50"
            >
              {L('✕ Not Received', 'రాలేదు')}
            </button>
            <button
              onClick={() => onUpdatePaymentStatus('pending')}
              disabled={processingPaid}
              className="border-2 border-amber-300 text-amber-700 font-bold py-2.5 rounded-xl text-xs disabled:opacity-50 active:bg-amber-50"
            >
              {L('⏳ Pending', 'పెండింగ్')}
            </button>
          </div>
        </div>
      )}

      <div className="px-3 pb-3 space-y-2">
        {!isApproved ? (
          <>
            {/* Pending: confirming the chosen pickup/delivery date approves the
                order. The confirm button stays disabled until a date is set. */}
            <div className={`grid gap-2 ${isUpi && isPaymentClaimed ? 'grid-cols-1' : 'grid-cols-2'}`}>
              {!(isUpi && isPaymentClaimed) && (
                <button
                  onClick={() => onApprove(fulfillmentDate)}
                  disabled={processing || !fulfillmentDate}
                  className="bg-green-600 text-white font-bold py-3 rounded-xl text-sm active:bg-green-700 disabled:opacity-50"
                >
                  {processing ? tx.approving : (isPickup ? tx.confirmPickupDate : tx.confirmDeliveryDate)}
                </button>
              )}
              <button
                onClick={onDecline}
                disabled={processing}
                className="border-2 border-red-300 text-red-600 font-bold py-3 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
              >
                {processing ? tx.declining : `✕ ${tx.decline}`}
              </button>
            </div>
            {!fulfillmentDate && !(isUpi && isPaymentClaimed) && (
              <p className="text-[11px] text-gray-500 text-center">{tx.chooseDateToApprove}</p>
            )}
          </>
        ) : isDelivery && riderAssigned ? (
          // Approved home-delivery in the rider flow: the farmer can still
          // cancel; the rider closes it out at the door.
          <button
            onClick={onDecline}
            disabled={processing}
            className="w-full border-2 border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
          >
            {processing ? tx.declining : `✕ ${tx.decline}`}
          </button>
        ) : isShipped ? (
          // Already shipped (courier / farmer-ships home delivery). Only the
          // BUYER confirms receipt now (Delivered / Received on their order
          // page), which stamps received_at and resolves the order — the farmer
          // just waits for that confirmation.
          <div className="bg-amber-50 border border-amber-200 rounded-xl px-3 py-2.5">
            <div className="text-center">
              <p className="text-xs font-bold text-amber-800">{L('🚚 Shipped', 'షిప్ చేయబడింది')}</p>
              <p className="text-[11px] text-amber-700 mt-0.5">
                {L('Awaiting buyer confirmation', 'కొనుగోలుదారు ధృవీకరణ కోసం వేచి ఉంది')}
              </p>
            </div>
          </div>
        ) : (
          // Approved farmer-fulfilled order, not yet shipped or collected. The
          // action depends on how it leaves the farm: a SELF-PICKUP order is
          // marked Picked Up (buyer collected — resolves immediately); a COURIER
          // or farmer-ships HOME-DELIVERY order is marked Shipped (→ buyer then
          // confirms Received). Only the one relevant button shows, never both.
          <>
            <button
              onClick={isPickup ? onMarkPickedUp : onMarkShipped}
              disabled={processing}
              className={`w-full text-white font-bold py-2.5 rounded-xl text-sm disabled:opacity-50 ${
                isPickup ? 'bg-green-600 active:bg-green-700' : 'bg-amber-600 active:bg-amber-700'
              }`}
            >
              {processing ? '…' : isPickup ? L('✓ Picked Up', 'తీసుకువెళ్ళారు') : L('🚚 Shipped', 'షిప్ చేయబడింది')}
            </button>
            <button
              onClick={onDecline}
              disabled={processing}
              className="w-full border-2 border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
            >
              {processing ? tx.declining : `✕ ${tx.decline}`}
            </button>
          </>
        )}
        {isCod && !isPaid && (
          <button
            onClick={onMarkPaid}
            disabled={processingPaid}
            className="w-full bg-amber-500 text-white font-bold py-3 rounded-xl text-sm active:bg-amber-600 disabled:opacity-50 flex items-center justify-center gap-1.5"
          >
            💵 {processingPaid ? tx.markingPaid : tx.markPaid}
          </button>
        )}
      </div>
    </div>
  )
}

/* ─── Home-delivery rider tag ──────────────────────────────── */
function DeliveryTagForFarmer({ order }: { order: FarmerOrder }) {
  const [rider, setRider] = useState<{ name: string | null; phone: string } | null>(null)
  const riderId = order.delivery_boy_id ?? null

  useEffect(() => {
    if (!riderId) { setRider(null); return }
    let cancelled = false
    supabase
      .from('delivery_boys')
      .select('name, phone')
      .eq('id', riderId)
      .maybeSingle()
      .then(({ data }) => {
        if (cancelled || !data) return
        setRider({ name: data.name ?? null, phone: data.phone as string })
      })
    return () => { cancelled = true }
  }, [riderId])

  const statusText = (() => {
    switch (order.delivery_status) {
      case 'assigned': return 'Rider assigned'
      case 'picked_up': return 'Picked up'
      case 'out_for_delivery': return 'Out for delivery'
      case 'delivered': return 'Delivered'
      default: return 'Waiting for rider'
    }
  })()

  return (
    <div className="bg-blue-50 border border-blue-200 rounded-xl px-3 py-2 mt-1 space-y-1.5">
      <p className="text-[10px] font-bold text-blue-800 uppercase tracking-wide">
        🛵 Home delivery · {statusText}
      </p>
      {rider ? (
        <div className="flex items-center justify-between gap-2">
          <div className="min-w-0">
            <p className="text-xs font-bold text-gray-900 truncate">{rider.name || 'Rider'}</p>
            <p className="text-[11px] text-gray-500">For pickup coordination</p>
          </div>
          <a
            href={`tel:${rider.phone}`}
            className="bg-blue-600 text-white font-bold text-xs px-3 py-2 rounded-xl whitespace-nowrap active:bg-blue-700"
          >
            📞 Call · {rider.phone}
          </a>
        </div>
      ) : (
        <p className="text-[11px] text-blue-700">
          A delivery boy will pick up the order. You&apos;ll see their contact here when assigned.
        </p>
      )}
    </div>
  )
}

'use client'

import { Suspense, useState, useEffect, useCallback } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { supabase } from '@/lib/supabase'
import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'
import OrderCard, { type FarmerOrder as Order, isResolved } from '@/components/farmer/OrderCard'
import { DeclineReasonSheet, DeclineSuccessSheet } from '@/components/farmer/DeclineSheets'

type StatusFilter = 'all' | 'pending' | 'approved' | 'completed' | 'declined' | 'cancelled'
type TimeFilter = 'today' | 'week' | 'month' | 'all'

// An order the farmer can still act on (approve/decline, mark picked-up/shipped,
// or acknowledge a buyer cancellation). Everything else is terminal history.
function isActionable(o: Order): boolean {
  if (o.status === 'pending') return true
  if (o.status === 'approved') return !isResolved(o)
  if (o.status === 'cancelled') return !o.acknowledged_at
  return false // declined is always terminal
}

// Which status bucket an order belongs to (drives the status filter chips).
function bucketOf(o: Order): Exclude<StatusFilter, 'all'> {
  if (o.status === 'pending') return 'pending'
  if (o.status === 'declined') return 'declined'
  if (o.status === 'cancelled') return 'cancelled'
  // approved: resolved (collected / received / delivered) → completed, else awaiting
  return isResolved(o) ? 'completed' : 'approved'
}

function OrdersPageInner() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const { tx, L } = useLang()
  const [orders, setOrders] = useState<Order[]>([])
  const [farmerId, setFarmerId] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all')
  const [timeFilter, setTimeFilter] = useState<TimeFilter>('all')
  const [processingOrderId, setProcessingOrderId] = useState<string | null>(null)
  const [processingPaidId, setProcessingPaidId] = useState<string | null>(null)
  const [decliningOrder, setDecliningOrder] = useState<Order | null>(null)
  const [declineResult, setDeclineResult] = useState<
    { buyerName: string | null; amount: number | null; refundInitiated: boolean } | null
  >(null)

  // Honour ?status=<bucket> and ?time=<window> deep links from the dashboard
  // (e.g. the pending banner opens ?status=pending; the "My order details" card
  // opens ?time=today).
  useEffect(() => {
    const s = searchParams.get('status')
    if (s && ['pending', 'approved', 'completed', 'declined', 'cancelled'].includes(s)) {
      setStatusFilter(s as StatusFilter)
    }
    const t = searchParams.get('time')
    if (t && ['today', 'week', 'month', 'all'].includes(t)) {
      setTimeFilter(t as TimeFilter)
    }
  }, [searchParams])

  // Silent refresh keeps the spinner only for the very first load.
  const load = useCallback(async (silent = false) => {
    const farmerId = localStorage.getItem('yff_farmer_id')
    if (!farmerId) { router.replace('/farmer/login'); return }
    setFarmerId(farmerId)

    if (!silent) setLoading(true)
    // Explicit columns: handover_otp is deliberately NOT fetched — the pickup
    // code must come from the customer, so the farmer's browser never sees it.
    // Every status is fetched (this page is the full orders hub).
    const { data } = await supabase
      .from('orders')
      .select('id, farmer_id, order_code, produce_listing_id, produce_name, quantity, unit, total_price, buyer_name, buyer_phone, pickup_location, status, payment_method, payment_status, utr_number, decline_reason, refund_status, refund_amount, refunded_at, delivery_type, delivery_status, delivery_boy_id, collected_at, shipped_at, received_at, fulfillment_date, created_at, acknowledged_at')
      .eq('farmer_id', farmerId)
      .order('created_at', { ascending: false })

    setOrders((data ?? []) as Order[])
    setLoading(false)
  }, [router])

  useEffect(() => { load() }, [load])

  // Keep this page live: a buyer can cancel after it loaded. Without this the
  // farmer would keep seeing the order as actionable — and could approve/ship a
  // cancelled order — until a manual refresh. Refetch (silently) on any order
  // change for this farmer, and whenever the tab regains focus as a safety net
  // for dropped websockets on spotty 4G.
  useEffect(() => {
    if (!farmerId) return
    const channel = supabase
      .channel(`farmer_orders_page_${farmerId}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'orders', filter: `farmer_id=eq.${farmerId}` },
        () => { void load(true) },
      )
      .subscribe()
    return () => { supabase.removeChannel(channel) }
  }, [farmerId, load])

  useEffect(() => {
    const refetch = () => { if (document.visibilityState === 'visible') void load(true) }
    document.addEventListener('visibilitychange', refetch)
    window.addEventListener('focus', refetch)
    return () => {
      document.removeEventListener('visibilitychange', refetch)
      window.removeEventListener('focus', refetch)
    }
  }, [load])

  /* ─── Order actions (mirror the dashboard) ─────────────────── */

  // Farmer sets/updates the pickup-or-delivery date on an order.
  const handleSetFulfillmentDate = async (orderId: string, date: string) => {
    const value = date || null
    setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, fulfillment_date: value } : o)))
    await supabase.from('orders').update({ fulfillment_date: value }).eq('id', orderId)
  }

  // Approving requires a pickup/delivery date; the order then stays as approved
  // until it's picked up / delivered.
  const handleApprove = async (orderId: string, date: string) => {
    if (!date) return
    setProcessingOrderId(orderId)
    // Guard on status='pending': if the buyer cancelled (or the order was
    // declined) since this list loaded, the update matches 0 rows so we never
    // resurrect a cancelled/declined order into 'approved'. Re-sync and tell the
    // farmer instead of silently flipping it back to active.
    const { data, error } = await supabase
      .from('orders')
      .update({ status: 'approved', fulfillment_date: date, confirmed_at: new Date().toISOString() })
      .eq('id', orderId)
      .eq('status', 'pending')
      .select('id')
    if (error || !data?.length) {
      await load(true)
      setProcessingOrderId(null)
      alert(L('This order can no longer be approved — the buyer may have cancelled it.', 'ఈ ఆర్డర్‌ను ఇప్పుడు ఆమోదించలేరు — కొనుగోలుదారు రద్దు చేసి ఉండవచ్చు.'))
      return
    }
    setOrders((prev) =>
      prev.map((o) => (o.id === orderId ? { ...o, status: 'approved', fulfillment_date: date } : o)),
    )
    setProcessingOrderId(null)
  }

  // Self-pickup: buyer collected — stamp collected_at (resolves the order).
  const handleMarkPickedUp = async (orderId: string) => {
    setProcessingOrderId(orderId)
    const res = await fetch(`/api/farmer/orders/${orderId}/picked-up`, { method: 'POST', credentials: 'same-origin' })
    if (res.ok) {
      setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, collected_at: new Date().toISOString() } : o)))
    } else {
      void load(true)
    }
    setProcessingOrderId(null)
  }

  // Courier / farmer-shipped home delivery: farmer hands over the parcel.
  const handleMarkShipped = async (orderId: string) => {
    setProcessingOrderId(orderId)
    const res = await fetch(`/api/farmer/orders/${orderId}/ship`, { method: 'POST', credentials: 'same-origin' })
    if (res.ok) {
      const json = (await res.json().catch(() => ({}))) as { shipped_at?: string }
      const shippedAt = json.shipped_at ?? new Date().toISOString()
      setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, shipped_at: shippedAt } : o)))
    } else {
      void load(true)
    }
    setProcessingOrderId(null)
  }

  // Farmer acknowledges a buyer-cancelled order (stamps acknowledged_at).
  const handleAcknowledgeCancel = async (orderId: string) => {
    setProcessingOrderId(orderId)
    try {
      const res = await fetch(`/api/farmer/orders/${orderId}/acknowledge`, { method: 'POST', credentials: 'same-origin' })
      if (res.ok) {
        setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, acknowledged_at: new Date().toISOString() } : o)))
      } else {
        const json = await res.json().catch(() => ({}))
        alert(json.error || L('Could not update. Please try again.', 'నవీకరించలేకపోయాం. మళ్ళీ ప్రయత్నించండి.'))
      }
    } catch {
      alert(L('Network error. Please try again.', 'నెట్‌వర్క్ సమస్య. మళ్ళీ ప్రయత్నించండి.'))
    } finally {
      setProcessingOrderId(null)
    }
  }

  const handleConfirmDecline = async (orderId: string, reason: string) => {
    const declined = decliningOrder
    setProcessingOrderId(orderId)
    try {
      const res = await fetch(`/api/farmer/orders/${orderId}/decline`, {
        method: 'POST',
        credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) {
        alert(json.error || L('Could not decline the order. Please try again.', 'ఆర్డర్ తిరస్కరించలేకపోయాం. మళ్ళీ ప్రయత్నించండి.'))
        return
      }
      const refundInitiated = !!json.refunded || !!json.refundStatus
      setOrders((prev) =>
        prev.map((o) =>
          o.id === orderId
            ? {
                ...o,
                status: 'declined',
                decline_reason: reason,
                refund_status: refundInitiated ? (o.refund_status ?? 'initiated') : o.refund_status,
                refund_amount: refundInitiated ? (o.refund_amount ?? o.total_price ?? null) : o.refund_amount,
              }
            : o,
        ),
      )
      setDeclineResult({
        buyerName: declined?.buyer_name ?? null,
        amount: declined?.total_price ?? null,
        refundInitiated,
      })
      setDecliningOrder(null)
    } catch {
      alert(L('Network error. Please try again.', 'నెట్‌వర్క్ సమస్య. మళ్ళీ ప్రయత్నించండి.'))
    } finally {
      setProcessingOrderId(null)
    }
  }

  const handleMarkPaid = async (orderId: string) => {
    setProcessingPaidId(orderId)
    await supabase.from('orders').update({ payment_status: 'completed', paid_at: new Date().toISOString() }).eq('id', orderId)
    setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, payment_status: 'completed' } : o)))
    setProcessingPaidId(null)
  }

  const handleUpdatePaymentStatus = async (orderId: string, status: 'completed' | 'failed' | 'pending') => {
    setProcessingPaidId(orderId)
    const update: Record<string, string> = { payment_status: status }
    if (status === 'completed') {
      update.status = 'approved'
      update.paid_at = new Date().toISOString()
      update.confirmed_at = new Date().toISOString()
    }
    // "Received & Approve" flips status to 'approved'; guard it on the order
    // still being pending so a buyer-cancelled order can't be resurrected. A
    // plain payment_status change (failed/pending) is harmless to apply.
    let query = supabase.from('orders').update(update).eq('id', orderId)
    if (status === 'completed') query = query.eq('status', 'pending')
    const { data, error } = await query.select('id')
    if (status === 'completed' && (error || !data?.length)) {
      await load(true)
      setProcessingPaidId(null)
      alert(L('This order can no longer be approved — the buyer may have cancelled it.', 'ఈ ఆర్డర్‌ను ఇప్పుడు ఆమోదించలేరు — కొనుగోలుదారు రద్దు చేసి ఉండవచ్చు.'))
      return
    }
    setOrders((prev) =>
      prev.map((o) =>
        o.id === orderId ? { ...o, payment_status: status, ...(status === 'completed' ? { status: 'approved' as const } : {}) } : o,
      ),
    )
    setProcessingPaidId(null)
  }

  /* ─── Filtering ────────────────────────────────────────────── */
  const timeStart = () => {
    if (timeFilter === 'today') {
      const d = new Date()
      d.setHours(0, 0, 0, 0)
      return d.getTime()
    }
    if (timeFilter === 'week') return Date.now() - 7 * 86400000
    if (timeFilter === 'month') return Date.now() - 30 * 86400000
    return 0 // all time
  }

  const start = timeStart()
  const filtered = orders.filter((o) => {
    if (new Date(o.created_at).getTime() < start) return false
    if (statusFilter === 'all') return true
    return bucketOf(o) === statusFilter
  })

  const revenue = filtered
    .filter((o) => o.status === 'approved')
    .reduce((sum, o) => sum + (o.total_price ?? 0), 0)

  // Per-bucket counts for the chips (respect the active time window).
  const inWindow = orders.filter((o) => new Date(o.created_at).getTime() >= start)
  const countFor = (s: StatusFilter) =>
    s === 'all' ? inWindow.length : inWindow.filter((o) => bucketOf(o) === s).length

  const STATUS_CHIPS: { key: StatusFilter; label: string }[] = [
    { key: 'all', label: L('All', 'అన్నీ') },
    { key: 'pending', label: L('Pending', 'పెండింగ్') },
    { key: 'approved', label: L('Approved', 'ఆమోదించారు') },
    { key: 'completed', label: L('Picked up', 'తీసుకున్నారు') },
    { key: 'declined', label: L('Declined', 'తిరస్కరించారు') },
    { key: 'cancelled', label: L('Cancelled', 'రద్దు చేశారు') },
  ]

  const TIME_CHIPS: { key: TimeFilter; label: string }[] = [
    { key: 'today', label: tx.filterToday },
    { key: 'week', label: tx.filterWeek },
    { key: 'month', label: tx.filterMonth },
    { key: 'all', label: L('All time', 'మొత్తం') },
  ]

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header */}
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <Link href="/farmer/dashboard" className="text-green-300 text-sm flex items-center gap-1 mb-4">
          ← {tx.back}
        </Link>
        <h1 className="text-white text-xl font-extrabold leading-tight">
          {L('Orders', 'ఆర్డర్లు')}
        </h1>
        <p className="text-green-400 text-sm mt-1">
          {L('All your orders in one place', 'మీ అన్ని ఆర్డర్లు ఒకే చోట')}
        </p>
      </div>

      <div className="px-4 -mt-5 space-y-4">
        {/* Status filter — scrollable chips with live counts */}
        <div className="bg-white rounded-2xl border border-gray-100 p-3">
          <div className="flex gap-2 overflow-x-auto scrollbar-hide">
            {STATUS_CHIPS.map(({ key, label }) => (
              <button
                key={key}
                onClick={() => setStatusFilter(key)}
                className={`flex-shrink-0 px-3 py-2 rounded-xl text-xs font-bold transition-colors whitespace-nowrap ${
                  statusFilter === key ? 'bg-green-700 text-white' : 'bg-gray-100 text-gray-600 active:bg-gray-200'
                }`}
              >
                {label} <span className={statusFilter === key ? 'text-green-200' : 'text-gray-400'}>({countFor(key)})</span>
              </button>
            ))}
          </div>
        </div>

        {/* Time filter */}
        <div className="bg-white rounded-2xl border border-gray-100 p-3 flex gap-2">
          {TIME_CHIPS.map(({ key, label }) => (
            <button
              key={key}
              onClick={() => setTimeFilter(key)}
              className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-colors ${
                timeFilter === key ? 'bg-green-700 text-white' : 'bg-gray-100 text-gray-600 active:bg-gray-200'
              }`}
            >
              {label}
            </button>
          ))}
        </div>

        {/* Revenue summary */}
        {revenue > 0 && (
          <div className="bg-green-50 border border-green-200 rounded-2xl p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-green-700 uppercase tracking-wide">
                {tx.totalRevenue}
              </p>
              <p className="text-3xl font-black text-green-800 mt-0.5">₹{revenue}</p>
            </div>
            <div className="text-4xl">💰</div>
          </div>
        )}

        {/* Order list */}
        {loading ? (
          <div className="text-center py-16">
            <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin mx-auto" />
            <p className="text-gray-500 text-sm mt-3">{tx.loadingLabel}</p>
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16">
            <div className="text-5xl mb-3">📭</div>
            <p className="font-semibold text-gray-500 text-sm">{L('No orders here', 'ఇక్కడ ఆర్డర్లు లేవు')}</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filtered.map((order) =>
              isActionable(order) ? (
                <OrderCard
                  key={order.id}
                  order={order}
                  processing={processingOrderId === order.id}
                  processingPaid={processingPaidId === order.id}
                  onApprove={(date) => handleApprove(order.id, date)}
                  onDecline={() => setDecliningOrder(order)}
                  onAcknowledge={() => handleAcknowledgeCancel(order.id)}
                  onMarkPaid={() => handleMarkPaid(order.id)}
                  onUpdatePaymentStatus={(s) => handleUpdatePaymentStatus(order.id, s)}
                  onSetFulfillmentDate={(d) => handleSetFulfillmentDate(order.id, d)}
                  onMarkPickedUp={() => handleMarkPickedUp(order.id)}
                  onMarkShipped={() => handleMarkShipped(order.id)}
                />
              ) : (
                <HistoryCard
                  key={order.id}
                  order={order}
                  onSetDate={(d) => handleSetFulfillmentDate(order.id, d)}
                />
              ),
            )}
          </div>
        )}
      </div>

      {/* Decline reason sheet */}
      {decliningOrder && (
        <DeclineReasonSheet
          order={decliningOrder}
          processing={processingOrderId === decliningOrder.id}
          onCancel={() => setDecliningOrder(null)}
          onConfirm={(reason) => handleConfirmDecline(decliningOrder.id, reason)}
        />
      )}

      {/* Refund confirmation after declining */}
      {declineResult && (
        <DeclineSuccessSheet result={declineResult} onClose={() => setDeclineResult(null)} />
      )}
    </main>
  )
}

