'use client'

import { useState, useEffect } from 'react'
import { useLang } from '@/lib/LanguageContext'

type Review = {
  id: string
  reviewer_name: string
  reviewer_location?: string
  star_rating: number
  review_text?: string
  produce_ordered?: string
  created_at: string
}

export default function ReviewsTab({
  reviews: initialReviews,
  farmerId,
}: {
  reviews: Record<string, unknown>[]
  farmerId: string
}) {
  const { tx, L } = useLang()
  const [reviews, setReviews] = useState<Review[]>(initialReviews as Review[])
  const [showForm, setShowForm] = useState(false)
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [rating, setRating] = useState(0)
  const [hoverRating, setHoverRating] = useState(0)
  const [reviewText, setReviewText] = useState('')
  const [produceBought, setProduceBought] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const [done, setDone] = useState(false)

  // Restore already-reviewed state from localStorage on mount
  useEffect(() => {
    if (localStorage.getItem(`yff_reviewed_${farmerId}`)) setDone(true)
  }, [farmerId])

  const avg =
    reviews.length > 0
      ? reviews.reduce((sum, r) => sum + r.star_rating, 0) / reviews.length
      : 0

  const counts = [5, 4, 3, 2, 1].map((star) => ({
    star,
    count: reviews.filter((r) => r.star_rating === star).length,
  }))

  const resetForm = () => {
    setName('')
    setPhone('')
    setRating(0)
    setHoverRating(0)
    setReviewText('')
    setProduceBought('')
    setError('')
  }

  const handleSubmit = async () => {
    if (!name.trim() || phone.replace(/\D/g, '').length < 10 || rating === 0) {
      setError(tx.reviewRequiredFields)
      return
    }
    setSubmitting(true)
    setError('')

    const res = await fetch('/api/reviews', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        farmer_id: farmerId,
        reviewer_name: name.trim(),
        reviewer_phone: phone.replace(/\D/g, '').slice(-10),
        star_rating: rating,
        review_text: reviewText.trim() || null,
        produce_ordered: produceBought.trim() || null,
      }),
    })

    const json = await res.json().catch(() => ({}))
    setSubmitting(false)

    if (res.status === 409 || json.error === 'already_reviewed') {
      localStorage.setItem(`yff_reviewed_${farmerId}`, '1')
      setDone(true)
      setShowForm(false)
      resetForm()
      return
    }

    if (!res.ok) {
      setError(json.error ?? tx.reviewError)
      return
    }

    if (json.review) setReviews((prev) => [json.review as Review, ...prev])
    localStorage.setItem(`yff_reviewed_${farmerId}`, '1')
    setDone(true)
    setShowForm(false)
    resetForm()
  }

  return (
    <div className="space-y-4">
      {/* CTA / success */}
      {done ? (
        <div className="bg-green-50 border border-green-200 rounded-xl p-4 text-center">
          <div className="text-3xl mb-1">⭐</div>
          <p className="font-bold text-green-800 text-sm">{tx.reviewSubmitted}</p>
        </div>
      ) : !showForm ? (
        <button
          onClick={() => setShowForm(true)}
          className="w-full bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-800"
        >
          ✏️ {tx.writeReview}
        </button>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100 bg-gray-50">
            <h3 className="font-extrabold text-gray-900 text-sm">{tx.writeReview}</h3>
            <button
              onClick={() => { setShowForm(false); resetForm() }}
              className="text-gray-400 text-2xl leading-none p-1"
            >
              ×
            </button>
          </div>

          <div className="p-4 space-y-4">
            {/* Star picker */}
            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-2">
                {tx.starRatingLabel}
              </label>
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map((s) => (
                  <button
                    key={s}
                    onClick={() => setRating(s)}
                    onMouseEnter={() => setHoverRating(s)}
                    onMouseLeave={() => setHoverRating(0)}
                    className="text-4xl leading-none transition-transform active:scale-110"
                    aria-label={`${s} stars`}
                  >
                    <span className={(hoverRating || rating) >= s ? 'text-yellow-400' : 'text-gray-200'}>
                      ★
                    </span>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.reviewerNameLabel}
              </label>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Ramya"
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
              />
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.reviewerPhoneLabel}
              </label>
              <div className="flex gap-2">
                <span className="flex items-center px-3 bg-gray-50 border border-gray-200 rounded-xl text-sm text-gray-600 font-medium">
                  +91
                </span>
                <input
                  type="tel"
                  inputMode="numeric"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  placeholder="9876543210"
                  maxLength={10}
                  className="flex-1 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
                />
              </div>
              <p className="text-[11px] text-gray-400 mt-1">{L('Used only to verify your review.', 'సమీక్షను ధృవీకరించడానికి మాత్రమే.')}</p>
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.produceOrderedLabel}
              </label>
              <input
                type="text"
                value={produceBought}
                onChange={(e) => setProduceBought(e.target.value)}
                placeholder="e.g. Tomato, Brinjal"
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
              />
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.reviewTextLabel}
              </label>
              <textarea
                value={reviewText}
                onChange={(e) => setReviewText(e.target.value.slice(0, 400))}
                placeholder="Share your experience with this farmer..."
                rows={3}
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm resize-none focus:border-green-500 focus:outline-none"
              />
              <p className="text-right text-xs text-gray-400">{reviewText.length}/400</p>
            </div>

            {error && (
              <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2">{error}</p>
            )}

            <div className="flex gap-3">
              <button
                onClick={() => { setShowForm(false); resetForm() }}
                className="flex-1 border-2 border-gray-200 text-gray-600 font-semibold py-3 rounded-xl text-sm"
              >
                {tx.cancelBtn}
              </button>
              <button
                onClick={handleSubmit}
                disabled={submitting}
                className="flex-1 bg-green-700 text-white font-bold py-3 rounded-xl text-sm disabled:opacity-50 active:bg-green-800"
              >
                {submitting ? tx.submittingReview : tx.submitReview}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Rating summary */}
      {reviews.length > 0 && (
        <div className="bg-white rounded-xl border border-gray-100 p-4">
          <div className="flex items-center gap-4">
            <div className="text-center">
              <p className="text-4xl font-bold text-gray-900">{avg.toFixed(1)}</p>
              <div className="flex justify-center mt-1">
                {[1, 2, 3, 4, 5].map((s) => (
                  <span key={s} className={`text-base ${s <= Math.round(avg) ? 'text-yellow-400' : 'text-gray-200'}`}>
                    ★
                  </span>
                ))}
              </div>
              <p className="text-xs text-gray-500 mt-1">{reviews.length} {tx.reviews}</p>
            </div>
            <div className="flex-1 space-y-1">
              {counts.map(({ star, count }) => (
                <div key={star} className="flex items-center gap-2">
                  <span className="text-xs text-gray-500 w-3">{star}</span>
                  <div className="flex-1 bg-gray-100 rounded-full h-2">
                    <div
                      className="bg-yellow-400 h-2 rounded-full"
                      style={{ width: reviews.length ? `${(count / reviews.length) * 100}%` : '0%' }}
                    />
                  </div>
                  <span className="text-xs text-gray-500 w-4">{count}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {reviews.length === 0 && !showForm && !done && (
        <div className="text-center py-8 text-gray-400 text-sm">{tx.noReviews}</div>
      )}

      {/* Individual reviews */}
      {reviews.length > 0 && (
        <div className="space-y-3">
          {reviews.map((review) => (
            <div key={review.id} className="bg-white rounded-xl border border-gray-100 p-4">
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-full bg-green-100 flex items-center justify-center text-green-800 font-bold text-sm flex-shrink-0">
                    {review.reviewer_name.slice(0, 2).toUpperCase()}
                  </div>
                  <div>
                    <p className="text-sm font-semibold text-gray-900">{review.reviewer_name}</p>
                    {review.reviewer_location && (
                      <p className="text-xs text-gray-500">{review.reviewer_location}</p>
                    )}
                  </div>
                </div>
                <div className="text-right flex-shrink-0">
                  <div className="flex justify-end">
                    {[1, 2, 3, 4, 5].map((s) => (
                      <span key={s} className={`text-sm ${s <= review.star_rating ? 'text-yellow-400' : 'text-gray-200'}`}>
                        ★
                      </span>
                    ))}
                  </div>
                  <p className="text-[10px] text-gray-400 mt-0.5">
                    {new Date(review.created_at).toLocaleDateString('en-IN', {
                      day: 'numeric',
                      month: 'short',
                      year: 'numeric',
                    })}
                  </p>
                </div>
              </div>
              {review.review_text && (
                <p className="text-sm text-gray-600 mt-3 leading-relaxed">{review.review_text}</p>
              )}
              {review.produce_ordered && (
                <p className="text-xs text-green-700 font-semibold mt-2">
                  {tx.bought} {review.produce_ordered}
                </p>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { supabase } from '@/lib/supabase'
import { notFound } from 'next/navigation'

export const dynamic = 'force-dynamic'
import { Suspense } from 'react'
import TopNav from '@/components/farmer/TopNav'
import FarmCover from '@/components/farmer/FarmCover'
import TrustStrip from '@/components/farmer/TrustStrip'
import TabSection from '@/components/farmer/TabSection'
import { CartFab } from '@/components/consumer/Cart'

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params

  const { data: farmer } = await supabase
    .from('farmers')
    .select('id, name, village, district, story_quote')
    .eq('slug', slug)
    .single()

  if (!farmer) return { title: 'Farmer not found' }

  const { data: firstPhoto } = await supabase
    .from('media')
    .select('url')
    .eq('farmer_id', farmer.id)
    .eq('type', 'photo')
    .order('sort_order', { ascending: true })
    .limit(1)
    .single()

  const title = `${farmer.name} — Natural farmer in ${farmer.village}`
  const description =
    farmer.story_quote ??
    `Buy natural produce directly from ${farmer.name}, ${farmer.village}, ${farmer.district}. No middlemen. No chemicals.`

  return {
    title: `${farmer.name}'s Farm — YourFamilyFarmer`,
    description,
    openGraph: {
      title,
      description,
      siteName: 'YourFamilyFarmer',
      ...(firstPhoto?.url ? { images: [{ url: firstPhoto.url, width: 1200, height: 630, alt: `${farmer.name}'s farm` }] } : {}),
    },
    twitter: {
      card: 'summary_large_image',
      title,
      description,
      ...(firstPhoto?.url ? { images: [firstPhoto.url] } : {}),
    },
  }
}

export default async function FarmerPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params

  const { data: farmer } = await supabase
    .from('farmers')
    .select('*')
    .eq('slug', slug)
    .eq('active', true)
    .single()

  if (!farmer) notFound()

  const { data: produce } = await supabase
    .from('produce_listings')
    .select('*')
    .eq('farmer_id', farmer.id)
    .order('created_at', { ascending: false })

  const { data: reviews } = await supabase
    .from('reviews')
    .select('*')
    .eq('farmer_id', farmer.id)
    .eq('approved', true)
    .order('created_at', { ascending: false })

  // Verified per-order buyer feedback (the ⭐ button consumers tap on their
  // orders) lives in produce_reviews, tied to a listing. Only feedback on a
  // completed order is approved/public. Surface it on the farmer's profile too —
  // tagged with the produce it was about — so consumer feedback isn't invisible
  // here, and fold it into the same Reviews tab + star average as written reviews.
  const { data: produceReviews } = await supabase
    .from('produce_reviews')
    .select('id, reviewer_name, star_rating, review_text, created_at, produce_listings(name)')
    .eq('farmer_id', farmer.id)
    .eq('approved', true)
    .order('created_at', { ascending: false })

  const mappedProduceReviews = (produceReviews ?? []).map((r) => {
    const pl = Array.isArray(r.produce_listings) ? r.produce_listings[0] : r.produce_listings
    return {
      id: r.id,
      reviewer_name: r.reviewer_name,
      star_rating: r.star_rating,
      review_text: r.review_text,
      produce_ordered: (pl as { name?: string } | null)?.name ?? null,
      created_at: r.created_at,
    }
  })

  // Both sources, newest first — one combined list for the Reviews tab.
  const allReviews = [...(reviews ?? []), ...mappedProduceReviews].sort(
    (a, b) => new Date(b.created_at as string).getTime() - new Date(a.created_at as string).getTime(),
  )

  // Star rating shown in the trust strip reflects all real feedback (written
  // reviews + verified order feedback). Falls back to the stored value if there
  // are no reviews yet.
  const ratingAvg =
    allReviews.length > 0
      ? Math.round(
          (allReviews.reduce((sum, r) => sum + ((r.star_rating as number) ?? 0), 0) / allReviews.length) * 10,
        ) / 10
      : (farmer.rating_avg ?? 0)

  const { data: media } = await supabase
    .from('media')
    .select('*')
    .eq('farmer_id', farmer.id)
    .order('sort_order', { ascending: true })

  return (
    <main className="min-h-screen bg-gray-50 pb-24">
      <TopNav regionSlug={farmer.region_slug} />
      <FarmCover farmer={farmer} />
      {/* Count only live listings — a produce the farmer has suspended (or that
          is still "coming soon") must not inflate the public "Produce now" stat. */}
      <TrustStrip
        farmer={{ ...farmer, rating_avg: ratingAvg }}
        produceCount={(produce ?? []).filter((p) => (p as { status?: string }).status === 'available').length}
      />
      <Suspense fallback={null}>
        <TabSection
          farmer={farmer}
          produce={produce ?? []}
          reviews={allReviews}
          media={media ?? []}
        />
      </Suspense>
      <CartFab />
    </main>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function admin() {
  return createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!)
}

// Recompute and cache a listing's rating aggregate after a review changes.
async function refreshAggregate(supabase: ReturnType<typeof admin>, listingId: string) {
  const { data: rows } = await supabase
    .from('produce_reviews')
    .select('star_rating')
    .eq('produce_listing_id', listingId)
    .eq('approved', true)
  const count = rows?.length ?? 0
  const avg = count > 0
    ? Math.round((rows!.reduce((s, r: { star_rating: number }) => s + r.star_rating, 0) / count) * 10) / 10
    : null
  await supabase
    .from('produce_listings')
    .update({ rating_avg: avg, review_count: count })
    .eq('id', listingId)
}

// GET /api/produce-reviews?listing_id=<uuid>
// Public — returns approved reviews + aggregate for a produce listing.
export async function GET(req: NextRequest) {
  const listingId = new URL(req.url).searchParams.get('listing_id') ?? ''
  if (!UUID_RE.test(listingId)) {
    return NextResponse.json({ error: 'Invalid listing id.' }, { status: 400 })
  }

  const supabase = admin()
  const { data: reviews, error } = await supabase
    .from('produce_reviews')
    .select('id, reviewer_name, star_rating, review_text, created_at')
    .eq('produce_listing_id', listingId)
    .eq('approved', true)
    .order('created_at', { ascending: false })
    .limit(100)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })

  const count = reviews?.length ?? 0
  const avg = count > 0
    ? Math.round((reviews!.reduce((s, r) => s + r.star_rating, 0) / count) * 10) / 10
    : null

  return NextResponse.json({ reviews: reviews ?? [], rating_avg: avg, review_count: count })
}

// POST /api/produce-reviews
// Verified buyer leaves a review on a produce they ordered, once the order is
// delivered / picked up. Body: { order_id, star_rating, review_text? }.
export async function POST(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })

  let body: { order_id?: unknown; star_rating?: unknown; review_text?: unknown }
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid request.' }, { status: 400 })
  }

  const orderId = typeof body.order_id === 'string' ? body.order_id : ''
  if (!UUID_RE.test(orderId)) {
    return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })
  }
  const rating = typeof body.star_rating === 'number' ? body.star_rating : NaN
  if (!Number.isInteger(rating) || rating < 1 || rating > 5) {
    return NextResponse.json({ error: 'Rating must be 1-5.' }, { status: 400 })
  }
  const text = typeof body.review_text === 'string' ? body.review_text.trim().slice(0, 600) : ''

  const supabase = admin()

  const { data: order, error: orderErr } = await supabase
    .from('orders')
    .select('id, consumer_id, produce_listing_id, farmer_id, buyer_name, buyer_phone, status, received_at, collected_at, delivered_at, delivery_status')
    .eq('id', orderId)
    .maybeSingle()

  if (orderErr) return NextResponse.json({ error: orderErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  if (!order.produce_listing_id) {
    return NextResponse.json({ error: 'This order cannot be reviewed.' }, { status: 400 })
  }

  // A buyer may give feedback on any of their own orders. Only feedback on a
  // *completed* order (delivered / picked up / received) is published publicly
  // and counts toward the produce's star average — that's a verified-buyer
  // rating. Feedback on a declined / cancelled / still-pending order is private
  // (approved = false): it's the buyer telling us about their experience, and is
  // never shown on the produce card so it can't unfairly drag the rating down.
  const completed =
    order.status !== 'declined' &&
    order.status !== 'cancelled' &&
    (!!order.received_at || !!order.collected_at || !!order.delivered_at || order.delivery_status === 'delivered')

  // One review per order.
  const { data: existing } = await supabase
    .from('produce_reviews')
    .select('id')
    .eq('order_id', orderId)
    .maybeSingle()
  if (existing) {
    return NextResponse.json({ error: 'already_reviewed' }, { status: 409 })
  }

  const { data: review, error: insErr } = await supabase
    .from('produce_reviews')
    .insert({
      order_id: orderId,
      produce_listing_id: order.produce_listing_id,
      farmer_id: order.farmer_id ?? null,
      consumer_id: order.consumer_id ?? null,
      reviewer_name: (order.buyer_name as string | null)?.trim()?.slice(0, 80) || 'Buyer',
      reviewer_phone: order.buyer_phone ? String(order.buyer_phone).replace(/\D/g, '').slice(-10) : null,
      star_rating: rating,
      review_text: text || null,
      approved: completed,
    })
    .select('id, reviewer_name, star_rating, review_text, created_at')
    .single()

  if (insErr) return NextResponse.json({ error: insErr.message }, { status: 500 })

  // Private (non-completed) feedback never affects the public average, so only
  // recompute the aggregate when a completed order added a public rating.
  if (completed) await refreshAggregate(supabase, order.produce_listing_id)

  return NextResponse.json({ review })
}

'use client'

import { useState } from 'react'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import type { MyReview } from '@/components/consumer/ProduceReviewBox'

// Shared feedback sheet, opened from an order card. A buyer can rate the produce
// for any of their orders. For a completed order it's a public verified-buyer
// rating; for a declined / cancelled / pending order it's private feedback about
// the order experience (kept off the public produce card).
export default function OrderFeedbackModal({
  orderId,
  produceName,
  completed,
  existing,
  onClose,
  onSaved,
}: {
  orderId: string
  produceName: string | null
  completed: boolean
  existing: MyReview | null
  onClose: () => void
  onSaved: () => void
}) {
  const { L, lang } = useLang()
  const name = localizeName(produceName, lang) || L('this produce', 'ఈ ఉత్పత్తి')
  const [rating, setRating] = useState(existing?.star_rating ?? 0)
  const [hover, setHover] = useState(0)
  const [text, setText] = useState(existing?.review_text ?? '')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const readOnly = Boolean(existing)

  const submit = async () => {
    if (rating === 0) { setError(L('Please tap a star to rate.', 'రేటింగ్ కోసం స్టార్ నొక్కండి.')); return }
    setSubmitting(true)
    setError('')
    const res = await fetch('/api/produce-reviews', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ order_id: orderId, star_rating: rating, review_text: text.trim() || null }),
    }).catch(() => null)
    const json = await res?.json().catch(() => ({})) as { review?: MyReview; error?: string }
    setSubmitting(false)
    if (!res || !res.ok || !json.review) {
      setError(json?.error === 'already_reviewed'
        ? L('You already gave feedback on this order.', 'మీరు ఇప్పటికే ఈ ఆర్డర్‌పై అభిప్రాయం ఇచ్చారు.')
        : (json?.error ?? L('Could not submit. Try again.', 'సమర్పించలేకపోయాం. మళ్ళీ ప్రయత్నించండి.')))
      return
    }
    onSaved()
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-end sm:items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-md p-5" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-1">
          <p className="font-extrabold text-gray-900">
            {readOnly
              ? L('Your feedback', 'మీ అభిప్రాయం')
              : completed
                ? `${L('Rate', 'రేటింగ్')} ${name}`
                : L('Give feedback', 'అభిప్రాయం ఇవ్వండి')}
          </p>
          <button onClick={onClose} className="text-gray-400 text-2xl leading-none p-1">×</button>
        </div>

        <p className="text-[11px] text-gray-500 mb-3">
          {readOnly
            ? L('Thanks for helping other buyers!', 'ఇతర కొనుగోలుదారులకు సహాయం చేసినందుకు ధన్యవాదాలు!')
            : completed
              ? L('How was it? Your review helps other buyers.', 'ఎలా ఉంది? మీ సమీక్ష ఇతర కొనుగోలుదారులకు సహాయపడుతుంది.')
              : L('Tell us about this order. This stays private and helps us improve.', 'ఈ ఆర్డర్ గురించి చెప్పండి. ఇది గోప్యంగా ఉంటుంది & మేము మెరుగుపడటానికి సహాయపడుతుంది.')}
        </p>

        <div className="flex gap-1 mb-3">
          {[1, 2, 3, 4, 5].map((s) => (
            <button
              key={s}
              type="button"
              disabled={readOnly}
              onClick={() => setRating(s)}
              onMouseEnter={() => !readOnly && setHover(s)}
              onMouseLeave={() => !readOnly && setHover(0)}
              className="text-4xl leading-none transition-transform active:scale-110 disabled:active:scale-100"
              aria-label={`${s} stars`}
            >
              <span className={(hover || rating) >= s ? 'text-yellow-400' : 'text-gray-200'}>★</span>
            </button>
          ))}
        </div>

        {readOnly ? (
          existing?.review_text && (
            <p className="text-sm text-gray-700 bg-gray-50 rounded-xl px-4 py-3 leading-relaxed">{existing.review_text}</p>
          )
        ) : (
          <textarea
            value={text}
            onChange={(e) => setText(e.target.value.slice(0, 600))}
            placeholder={L('Share a few words (optional)', 'కొన్ని మాటలు రాయండి (ఐచ్ఛికం)')}
            rows={3}
            className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm resize-none focus:border-green-500 focus:outline-none"
          />
        )}

        {error && <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2 mt-2">{error}</p>}

        {!readOnly && (
          <button
            type="button"
            onClick={submit}
            disabled={submitting}
            className="mt-3 w-full bg-green-700 text-white font-bold py-3 rounded-xl text-sm disabled:opacity-50 active:bg-green-800"
          >
            {submitting ? L('Submitting…', 'సమర్పిస్తోంది…') : L('Submit feedback', 'అభిప్రాయం సమర్పించు')}
          </button>
        )}
      </div>
    </div>
  )
}

