    const shippedAt = json.shipped_at ?? new Date().toISOString()
    setPendingOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, shipped_at: shippedAt } : o)))
  } else {
    void loadDashboard() // re-sync on failure
  }
  setProcessingOrderId(null)
}

